<script lang="ts">
import {onMount} from 'svelte';import type {Race,Runner} from '../data/types';import type {ReferenceData} from '../data/reference';import {runnerName,runnerOutfit} from '../data/reference';import {careerReference,scenarioName,careerDate} from '../data/career-display';import {formatRaceTime} from '../data/race-time';
import StarRating from './StarRating.svelte';import {totalSkillCost,skillCostHelp} from '../data/skill-cost';
import UmaPortrait from './UmaPortrait.svelte';import RatingBadge from './RatingBadge.svelte';import CopyTrainer from './CopyTrainer.svelte';import CareerBuild from './CareerBuild.svelte';import CareerSupport from './CareerSupport.svelte';import CareerFactors from './CareerFactors.svelte';import LegacyFamily from './LegacyFamily.svelte';
export let runner:Runner;export let race:Race;export let reference:ReferenceData|null;export let onClose:()=>void;
let dialog:HTMLDialogElement;onMount(()=>dialog.showModal());
$: career=runner.career;
$: sp=totalSkillCost(career?.skills??runner.skills);
$: epithet=career?.epithetId?careerReference.epithets[career.epithetId]??`Epithet ${career.epithetId}`:null;
$: facts=[...(career?.scenarioId!=null?[['Scenario',scenarioName(career.scenarioId)]]:[]),['Completed',career?.createdAt?formatRaceTime(career.createdAt):'Not recorded'],['Career wins',(career?.wins??runner.raceWinCount)?.toLocaleString()??'—'],['Fans',(career?.fans??runner.fanCount)?.toLocaleString()??'—'],['SP',`${sp.total.toLocaleString()}${sp.unknown?' + unknown':''}`]];
const grade=(g:number|undefined)=>({100:'G1',200:'G2',300:'G3',400:'OP',700:'Pre-OP',800:'Maiden',900:'Debut'} as Record<number,string>)[g??-1]??'';
</script>
<dialog bind:this={dialog} class="career-modal" aria-labelledby="career-title" onclose={onClose} onclick={e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}}} onkeydown={e=>{if(e.key==='Escape')e.stopPropagation();}}>
  <div class="career-modal-heading"><div><span class="eyebrow">UMA CAREER</span><h2 id="career-title">{runnerName(reference,runner)}</h2></div><button class="icon-button" aria-label="Close career" onclick={()=>dialog.close()}>×</button></div>
  <div class="career-modal-body">
    <section class="career-hero"><div class="career-identity"><UmaPortrait {runner} size={88}/><div><span class="outfit">{runnerOutfit(reference,runner)??'Outfit not recorded'}</span><h3>{runnerName(reference,runner)}</h3>{#if career?.stars??runner.starCount}<div class="career-stars"><StarRating count={career?.stars??runner.starCount??0} size={18}/></div>{/if}{#if epithet}<span class="epithet">{epithet}</span>{/if}<div class="owner"><b>{runner.trainer??career?.trainerName??'Trainer not recorded'}</b><CopyTrainer value={runner.trainerId??career?.trainerId}/></div></div><RatingBadge score={runner.rankScore??career?.score} rank={career?.rank} large/></div><CareerBuild stats={career&&Object.values(career.stats).some(v=>v!==null)?career.stats:runner.stats} aptitudes={career&&Object.values(career.aptitudes).some(v=>v!==null)?career.aptitudes:runner.aptitudes}/></section>
    <section class="career-section"><h3>Support cards <small>Open in GameTora ↗</small></h3>{#if career?.supports?.length}<div class="support-deck">{#each [...career.supports].sort((a,b)=>Number(a.borrowed===true||a.position===6)-Number(b.borrowed===true||b.position===6)||(a.position??0)-(b.position??0)) as card}<CareerSupport {card}/>{/each}</div>{:else}<p class="missing">Support deck not included in this capture.</p>{/if}</section>
    <section class="career-section"><h3>Career stats</h3><dl class="career-facts">{#each facts as [name,value]}<div><dt title={name==='SP'?skillCostHelp:undefined}>{#if name==='SP'}<img class="sp-icon" src="/career/sp.png" alt=""/>{/if}{name}</dt><dd>{value}</dd></div>{/each}</dl>{#if career?.factors?.length}<details class="career-disclosure"><summary>Own sparks · {career.factors.length}</summary><CareerFactors factors={career.factors} skills={career.skills}/>{#if career.extendedFactors?.length}<h4>Extended sparks</h4><CareerFactors factors={career.extendedFactors} skills={career.skills}/>{/if}</details>{/if}{#if career?.epithetIds.length}<details class="career-disclosure"><summary>Earned epithets · {career.epithetIds.length}</summary><div class="epithets">{#each career.epithetIds as id}<span>{careerReference.epithets[id]??`Epithet ${id}`}</span>{/each}</div></details>{/if}</section>
    <details class="career-disclosure race-history"><summary>Race history <small>{career?.races?.length??'—'} races</small></summary>{#if career?.races?.length}<div class="history-scroll"><table><thead><tr><th>Date</th><th>Race</th><th>Conditions</th><th>Place</th><th>Style</th></tr></thead><tbody>{#each career.races as result}{@const raceInfo=careerReference.programs[result.programId]}<tr><td>{careerDate(result.turn,career.scenarioId)}</td><td><b>{raceInfo?.name??`Race ${result.programId}`}</b><small>{grade(raceInfo?.grade)} {reference?.courses[raceInfo?.courseId]?.name??''}</small></td><td>{({1:'Sunny',2:'Cloudy',3:'Rain',4:'Snow'} as Record<number,string>)[result.weather??0]??'—'}<small>{({1:'Firm',2:'Good',3:'Soft',4:'Heavy'} as Record<number,string>)[result.ground??0]??'—'}</small></td><td class:winner={result.place===1}>{result.place??'—'}</td><td>{({1:'Front',2:'Pace',3:'Late',4:'End'} as Record<number,string>)[result.style??0]??'—'}</td></tr>{/each}</tbody></table></div>{:else}<p class="missing">Race history not included in this capture.</p>{/if}</details>
    <section class="career-section legacy-section"><h3>Legacy {'\u0055mamusume'} <small>Parents &amp; grandparents</small></h3>{#if career?.legacies.length}{#each [1,2] as index}<LegacyFamily {index} {career} trainee={runner} {reference} runners={race.runners}/>{/each}{:else}<p class="missing">Legacy information not included in this capture.</p>{/if}</section>
  </div>
</dialog>
<style>
.career-modal{width:min(1160px,calc(100vw - 48px));max-width:none;max-height:calc(100vh - 48px);padding:0;margin:auto;background:var(--panel);color:var(--text);border:1px solid var(--border);border-radius:14px;box-shadow:var(--shadow);overflow:hidden}.career-modal::backdrop{background:#000a;backdrop-filter:blur(4px)}.career-modal[open]{display:flex;flex-direction:column}.career-modal-heading{display:flex;justify-content:space-between;align-items:center;padding:17px 24px;border-bottom:1px solid var(--border);flex:none}.career-modal-heading h2{font-size:var(--font-22);margin:4px 0 0}.career-modal-heading button{font-size:var(--font-24)}.career-modal-body{padding:24px;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin}.career-hero{padding:20px;border:1px solid var(--border);border-radius:10px;background:linear-gradient(115deg,var(--panel-raised),var(--panel))}.career-identity{display:flex;align-items:center;gap:20px;margin-bottom:22px}.career-identity>div{flex:1;min-width:0}.career-identity :global(.rating){flex:none}.outfit{color:var(--muted);font-size:var(--font-12)}.career-stars{margin:0 0 10px}.career-identity h3{font-size:var(--font-27);margin:5px 0 9px}.epithet{display:inline-block;background:linear-gradient(100deg,#785d27,#c38a2c);border:1px solid #d0a951;color:#fff3ce;padding:4px 14px;border-radius:4px;font-size:var(--font-12);margin-bottom:10px}.owner{display:flex;gap:12px;align-items:center;flex-wrap:wrap;font-size:var(--font-13)}.owner b{font-weight:550}.career-section{margin-top:25px}.career-section>h3{display:flex;justify-content:space-between;align-items:baseline;gap:12px;margin:0 0 13px;font-size:var(--font-18)}h3 small{font-size:var(--font-11);font-weight:400;color:var(--muted)}.support-deck{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:13px}.career-facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));margin:0;border:1px solid var(--border);border-radius:9px;overflow:hidden}.career-facts>div{padding:12px 14px;border-bottom:1px solid var(--border);border-right:1px solid var(--border)}dt{display:flex;align-items:center;gap:5px;min-height:17px;font-size:var(--font-10);color:var(--muted);margin-bottom:7px}.sp-icon{width:17px;height:17px;object-fit:contain}dd{font-size:var(--font-13);font-weight:550;margin:0;line-height:1.5;overflow-wrap:anywhere}.career-disclosure{padding:14px 0;border-bottom:1px solid var(--border)}.career-disclosure summary{cursor:pointer;font-size:var(--font-13);font-weight:550}.career-disclosure[open]>summary{margin-bottom:15px}summary small{font-weight:400;color:var(--muted);margin-left:10px}.history-scroll{overflow:auto;max-height:330px}th{top:0;font-size:var(--font-10)}td{font-size:var(--font-12)}td b{font-weight:550}.winner{color:var(--accent-text);font-weight:650}.missing{font-size:var(--font-12);line-height:1.6;color:var(--muted);margin:10px 0}.legacy-section :global(.legacy-family){margin-top:15px}.epithets{display:flex;flex-wrap:wrap;gap:7px}.epithets span{border:1px solid var(--border);border-radius:4px;padding:5px 9px;font-size:var(--font-11)}@media(max-width:850px){.career-modal-body{padding:17px}.career-hero{padding:15px}.career-identity{gap:12px}.career-stars{margin:0 0 10px}.career-identity h3{font-size:var(--font-21)}.support-deck{gap:8px}.career-facts{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
